reps = {}
donation_history = {}  # agent -> list of last 20 actions

def evaluate(current_reputation, observation, my_history, round_num):
    donor = observation['donor']
    recipient = observation['recipient']
    action = observation['action']

    # Update donation history for donor
    if donor not in donation_history:
        donation_history[donor] = []
    donation_history[donor].append(action)
    if len(donation_history[donor]) > 20:
        donation_history[donor].pop(0)

    # Compute recent donation rate for donor
    recent = donation_history[donor]
    if recent:
        donate_count = sum(1 for a in recent if a == 'donate')
        rate = donate_count / len(recent)
    else:
        rate = 0.0

    # Base update amounts (similar to original)
    if action == 'donate':
        if reps.get(recipient, 0.0) > 0:
            base = 0.2
        else:
            base = 0.05
        # Boost reputation more if donor has been cooperative recently
        if rate > 0.5:
            base += 0.1
    else:  # not donate
        if reps.get(recipient, 0.0) > 0:
            base = -0.3
        else:
            base = -0.05
        # Reduce penalty if donor is generally cooperative (allow occasional defection)
        if rate > 0.5:
            base += 0.1  # makes penalty less negative

    new_rep = current_reputation + base
    new_rep = max(-1.0, min(1.0, new_rep))
    reps[donor] = new_rep
    return new_rep

